CREATE TABLE IF NOT EXISTS "Cards"("Id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"CardType" INTEGER NOT NULL,"CardNumber" TEXT NOT NULL,"ExpirationDate" TIMESTAMP NOT NULL,"IsActive" BOOLEAN NOT NULL,"CardNetwork" INTEGER NOT NULL,"BankId" BIGINT NOT NULL,"CardName" TEXT NULL,"CreatedAt" TIMESTAMP NOT NULL DEFAULT (now() AT TIME ZONE 'utc'),"UpdatedAt" TIMESTAMP NULL,CONSTRAINT "FK_Cards_Banks_BankId" FOREIGN KEY ("BankId") REFERENCES "Banks"("Id") ON DELETE RESTRICT);
